// data/missions.js — OWNED BY: builder B (People & Missions). The mission pool (v0.3 §3).
//
// Shape: { id, title, type, ...params, by?: [npcIds], first?: true, ask, progress, done, recv?, reward }
//   by     — only these givers are dealt it (it is written in their voice). No `by` = any giver may relay it.
//   first  — when the giver is dealt it, it is their opening mission.
//   recv   — deliver only: what the recipient says when you arrive.
// Text substitutions: {have} {n} {gold} {cost} {name} (the giver's short name) {to} (deliver target's name)
//   {where} (deliver: rough direction to the target) {biome} (the mission's biome name).
//
// Types (implemented in game/quests.js):
//   kill {n, biome?: 'here'|0-4, where?: 'dungeon'}   pay {gold}            far                     dex {n}
//   chest {n?, biome?}        boss {n?}               dclear {n?, biome?, dtype?}  enter {n?, biome?}
//   potion {n} (potion kinds identified)              throw {n} (poison potions thrown)          rare {n?}
//   hoard {gold} (carry it)   travel {biome}          deliver (walk to another of this run's givers)
//   camp {n?, biome?}         spell {n, spell?}       learn {n}             level {n}   walk {n} (steps)
//   nuke {n} (kills in one nuke)                      tele {n} (teleports: potion or Gate)
// Biomes: 0 Jungle · 1 Swamp · 2 Castle Ruins · 3 Mountains · 4 Desert.
// Rewards: { xp, gold, gear: { kind?, type?, slot?, q? }, scroll: spellId, potion: { pot, n } }.

